import { createHash } from 'node:crypto';
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';
import { canonicalSha256 } from '../core/canonical-json.mjs';
const LANGUAGE_BY_EXT=new Map([['.js','javascript'],['.mjs','javascript'],['.cjs','javascript'],['.ts','typescript'],['.tsx','typescript'],['.py','python'],['.rs','rust'],['.go','go']]);
async function walk(root,current=root){const entries=await readdir(current,{withFileTypes:true});const files=[];for(const entry of entries){if(['.git','node_modules','dist','coverage'].includes(entry.name))continue;const file=path.join(current,entry.name);if(entry.isDirectory())files.push(...await walk(root,file));else files.push(file);}return files;}
function lineOf(text,index){return text.slice(0,index).split('\n').length;}
function braceBody(text,start){const open=text.indexOf('{',start);if(open<0)return text.slice(start,text.indexOf('\n',start)>0?text.indexOf('\n',start):text.length);let depth=0;for(let i=open;i<text.length;i++){if(text[i]==='{')depth++;else if(text[i]==='}'&&--depth===0)return text.slice(start,i+1);}return text.slice(start);}
function indentationBody(text,start){const lineStart=text.lastIndexOf('\n',start)+1;const base=(text.slice(lineStart,start).match(/^\s*/)?.[0].length??0);const lines=text.slice(lineStart).split('\n');const out=[lines[0]];for(let i=1;i<lines.length;i++){if(!lines[i].trim()){out.push(lines[i]);continue;}const indent=lines[i].match(/^\s*/)[0].length;if(indent<=base)break;out.push(lines[i]);}return out.join('\n');}
function patterns(language){if(['javascript','typescript'].includes(language))return[{kind:'function',re:/(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)\s*\(/g},{kind:'class',re:/(?:export\s+)?class\s+([A-Za-z_$][\w$]*)/g},{kind:'function',re:/(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>/g}];if(language==='python')return[{kind:'function',re:/^\s*def\s+([A-Za-z_]\w*)\s*\(/gm},{kind:'class',re:/^\s*class\s+([A-Za-z_]\w*)/gm}];if(language==='rust')return[{kind:'function',re:/\bfn\s+([A-Za-z_]\w*)\s*\(/g},{kind:'struct',re:/\bstruct\s+([A-Za-z_]\w*)/g},{kind:'enum',re:/\benum\s+([A-Za-z_]\w*)/g}];if(language==='go')return[{kind:'function',re:/\bfunc\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*\(/g},{kind:'type',re:/\btype\s+([A-Za-z_]\w*)\s+(?:struct|interface)\b/g}];return[];}
function symbolId(relative,kind,name){return `S${createHash('sha256').update(`${relative}\0${kind}\0${name}`).digest('hex').slice(0,14)}`;}
export async function buildSemanticAbi({root,languages,previous=null}){const absolute=path.resolve(root);const allowed=new Set(languages??['javascript','typescript','python','rust','go']);const symbols=[];for(const file of await walk(absolute)){const language=LANGUAGE_BY_EXT.get(path.extname(file));if(!allowed.has(language))continue;const text=await readFile(file,'utf8');const relative=path.relative(absolute,file).split(path.sep).join('/');for(const pattern of patterns(language)){pattern.re.lastIndex=0;let match;while((match=pattern.re.exec(text))){const start=match.index;const body=language==='python'?indentationBody(text,start):braceBody(text,start);const name=match[1];symbols.push(Object.freeze({symbolId:symbolId(relative,pattern.kind,name),name,kind:pattern.kind,language,file:relative,startLine:lineOf(text,start),endLine:lineOf(text,start)+body.split('\n').length-1,contentHash:createHash('sha256').update(body).digest('hex'),body}));}}}symbols.sort((a,b)=>a.symbolId.localeCompare(b.symbolId));const previousIds=new Set((previous?.symbols??[]).map((item)=>item.symbolId));const payload={schemaVersion:1,root:'.',symbols,added:symbols.filter((item)=>!previousIds.has(item.symbolId)).map((item)=>item.symbolId)};return Object.freeze({...payload,abiSha256:canonicalSha256({...payload,symbols:symbols.map(({body,...rest})=>rest)})});}
export function fetchSemanticSymbol({abi,symbolId,expectedHash}){const symbol=abi.symbols.find((item)=>item.symbolId===symbolId);if(!symbol)throw new Error(`Unknown semantic symbol ${symbolId}`);if(expectedHash&&symbol.contentHash!==expectedHash)throw new Error(`Stale semantic symbol ${symbolId}: expected ${expectedHash}, current ${symbol.contentHash}`);return Object.freeze({...symbol,directDependencies:[],tests:[],callSites:[]});}
